--- index.html
+++ index.html
@@ -26,4 +26,19 @@
 <div class="hud-right"><button class="skill-button interact" id="interact" aria-label="Etkileşim"><span class="icon">✧</span><span class="key">ETKİLEŞ</span></button><button class="skill-button skill1" id="skill" aria-label="Kor alevi"><span class="icon">♨</span><span class="key">KOR ALEVİ · Q</span><span class="cooldown"></span></button><button class="skill-button skill2" id="skill2" aria-label="Kül patlaması"><span class="icon">✹</span><span class="key">KÜL PATLAMASI · E</span><span class="cooldown"></span></button><button class="skill-button dodge" id="dodge" aria-label="Atıl"><span class="icon">➤</span><span class="key">ATIL · SPACE</span></button><button class="skill-button attack" id="attack" aria-label="Saldır"><span class="icon">⚔</span><span class="key">SALDIR · BASILI TUT</span></button></div>
 <div class="joystick" id="joystick"><div class="stick" id="stick"></div></div>
 <div class="modal-backdrop" id="backdrop"><section class="modal" id="modal"></section></div></main>
 <script>
+const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');const game=document.querySelector('#game');
+let W=0,H=0,dpr=1;function resize(){dpr=Math.min(devicePixelRatio||1,2);W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
+const player={x:0,y:0,r:13,hp:100,maxHp:100,mp:60,maxMp:60,xp:0,next:100,level:1,dmg:12,gold:42,faceX:1,faceY:0,invuln:0,dash:0};let enemies=[],drops=[],particles=[],inventory=[],materials={"Kül Özü":1,"Kurt Postu":0,"Demir Cevheri":2},kills=0,attackHeld=false,attackTimer=0,skillCD=0,skill2CD=0,questDone=false,mastery={"Kısa Kılıç":0,"Kor Alevi":0,"Kül Patlaması":0},treePoints=0,treeBought={};const keys={},joy={x:0,y:0},camera={x:0,y:0};
+function spawnEnemy(x,y,type='wolf'){enemies.push({x,y,type,r:type==='brute'?18:13,hp:type==='brute'?55:32,max:type==='brute'?55:32,speed:type==='brute'?25:37,attack:0,wind:0,hitFlash:0,phase:Math.random()*5})}
+for(let i=0;i<7;i++)spawnEnemy((Math.random()-.5)*620,(Math.random()-.5)*470,i===6?'brute':'wolf');
+function rand(a,b){return a+Math.random()*(b-a)}function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function particle(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-90,90),vy:rand(-100,55),life:rand(.25,.65),max:.65,color,r:rand(2,4)})}
+function updateHUD(){document.querySelector('#hp-text').textContent=Math.ceil(player.hp);document.querySelector('#mp-text').textContent=Math.floor(player.mp);document.querySelector('#level').textContent=player.level;document.querySelector('#xp').textContent=player.xp;document.querySelector('#xp-next').textContent=player.next;document.querySelector('#dmg').textContent=player.dmg;document.querySelector('#gold').textContent=player.gold;document.querySelector('#item-count').textContent=inventory.length;document.querySelector('.health').style.setProperty('--fill',`${player.hp/player.maxHp*100}%`);document.querySelector('.mana').style.setProperty('--fill',`${player.mp/player.maxMp*100}%`);document.querySelector('#quest-copy').textContent=questDone?'Tamamlandı · Ödül alındı':'5 kül kurdu avla · Ödül: 60 XP + 1 Öz'}
+function gainXP(n){player.xp+=n;if(player.xp>=player.next){player.xp-=player.next;player.level++;player.next=Math.round(player.next*1.35);player.maxHp+=12;player.hp=player.maxHp;player.dmg+=2;treePoints++;notify('SEVİYE ATLADIN',`Seviye ${player.level} · +1 Yetenek Puanı`)}updateHUD()}
+let labelTimer=0;function notify(title,copy){document.querySelector('#quest-title').textContent=title;document.querySelector('#quest-copy').textContent=copy;labelTimer=3}
+function aimTarget(range=110){let best=null,bd=range;for(const e of enemies){let d=dist(player,e);if(d<bd){bd=d;best=e}}return best}
+function attack(){if(attackTimer>0)return;attackTimer=.38;const e=aimTarget(78);if(e){const a=Math.atan2(e.y-player.y,e.x-player.x);player.faceX=Math.cos(a);player.faceY=Math.sin(a);e.hp-=player.dmg;e.hitFlash=.14;particle(e.x,e.y,'#f3c477',7);mastery['Kısa Kılıç']+=1;if(e.hp<=0)killEnemy(e)}else{particle(player.x+player.faceX*25,player.y+player.faceY*25,'#d7c18e',3)}}
+function castSkill(which){const cd=which===1?skillCD:skill2CD;if(cd>0)return;const cost=which===1?16:28;if(player.mp<cost){notify('ÖZ YETERSİZ','Özün yenilenmesini bekle.');return}player.mp-=cost;if(which===1){skillCD=3.1;mastery['Kor Alevi']+=1;let e=aimTarget(225);let tx=e?e.x:player.x+player.faceX*150,ty=e?e.y:player.y+player.faceY*150;particle(tx,ty,'#ff9b48',24);for(const enemy of enemies)if(Math.hypot(enemy.x-tx,enemy.y-ty)<50){enemy.hp-=31+player.level*3;enemy.hitFlash=.2;if(enemy.hp<=0)killEnemy(enemy)}}else{skill2CD=6.5;mastery['Kül Patlaması']++;particle(player.x,player.y,'#9b8cff',30);for(const enemy of enemies)if(dist(player,enemy)<105){enemy.hp-=23+player.level*2;enemy.hitFlash=.2;if(enemy.hp<=0)killEnemy(enemy)}}updateHUD()}
+function killEnemy(e){let idx=enemies.indexOf(e);if(idx<0)return;enemies.splice(idx,1);kills++;gainXP(e.type==='brute'?38:22);particle(e.x,e.y,'#d7ae6d',18);drops.push({x:e.x,y:e.y,type:Math.random()<.22?'gear':Math.random()<.5?'ore':'hide',life:40});if(!questDone&&kills>=5){questDone=true;gainXP(60);materials['Kül Özü']++;player.gold+=30;notify('KAMP GÖREVİ TAMAMLANDI','+60 XP · +1 Kül Özü · +30 Altın')}if(enemies.length<5){setTimeout(()=>{if(enemies.length<7)spawnEnemy(rand(-300,300),rand(-230,230),Math.random()<.18?'brute':'wolf')},1300)}}
+function nearestDrop(){let d=null,bd=65;for(let x of drops){let q=dist(player,x);if(q<bd){bd=q;d=x}}return d}function interact(){let d=nearestDrop();if(d){let i=drops.indexOf(d);drops.splice(i,1);if(d.type==='ore'){materials['Demir Cevheri']++;notify('DEMİR CEVHERİ','Malzemeler çantana eklendi.')}else if(d.type==='hide'){materials['Kurt Postu']++;notify('KURT POSTU','Malzemeler çantana eklendi.')}else{let item={name:Math.random()<.5?'Kül Yarması':'Gözcü Miğferi',slot:Math.random()<.5?'Silah':'Miğfer',rarity:Math.random()<.18?'Efsanevi':'Büyülü',dmg:Math.floor(rand(3,8))+player.level*2};inventory.push(item);notify('GANİMET BULUNDU',`${item.rarity} ${item.name} · +${item.dmg} Hasar`) }updateHUD();return}let e=aimTarget(90);if(e){notify('DÜŞMAN YAKIN','Saldırmak için ⚔ düğmesine bas.');return}notify('KÜL GEÇİDİ','Keşfet, düşmanları alt et ve ganimetini topla.')}
+function dodge(){if(player.dash>0||player.mp<8)return;player.mp-=8;player.dash=.22;player.invuln=.45;let dx=joy.x||((keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0)),dy=joy.y||((keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0));if(!dx&&!dy){dx=player.faceX;dy=player.faceY}let l=Math.hypot(dx,dy)||1;player.vx=dx/l*490;player.vy=dy/l*490;particle(player.x,player.y,'#a8c9bd',8);updateHUD()}

