function dodge(){if(player.dash>0||player.mp<8)return;player.mp-=8;player.dash=.22;player.invuln=.45;let dx=joy.x||((keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0)),dy=joy.y||((keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0));if(!dx&&!dy){dx=player.faceX;dy=player.faceY}let l=Math.hypot(dx,dy)||1;player.vx=dx/l*490;player.vy=dy/l*490;particle(player.x,player.y,'#a8c9bd',8);updateHUD()}
function drawGround(){ctx.fillStyle='#28372b';ctx.fillRect(-W,-H,W*3,H*3);ctx.strokeStyle='#71835b12';ctx.lineWidth=1;for(let x=-1000;x<1000;x+=64){ctx.beginPath();ctx.moveTo(x,-1000);ctx.lineTo(x,1000);ctx.stroke()}for(let y=-1000;y<1000;y+=64){ctx.beginPath();ctx.moveTo(-1000,y);ctx.lineTo(1000,y);ctx.stroke()}for(let i=0;i<38;i++){let x=Math.sin(i*134.4)*420,y=Math.cos(i*64.2)*330;ctx.fillStyle=i%3?'#1f2c23':'#354330';ctx.beginPath();ctx.ellipse(x,y,randSeed(i,8,19),randSeed(i,5,12),i,0,Math.PI*2);ctx.fill();if(i%5===0){ctx.strokeStyle='#746d4b77';ctx.beginPath();ctx.moveTo(x-7,y+6);ctx.lineTo(x+8,y-7);ctx.stroke()}}}
function randSeed(i,a,b){let v=Math.sin(i*127.1+83.3)*43758.5453;return a+(v-Math.floor(v))*(b-a)}
function drawEnemy(e){let x=e.x,y=e.y;ctx.save();ctx.translate(x,y);if(e.type==='brute'){ctx.fillStyle='#32372e';ctx.beginPath();ctx.ellipse(0,8,16,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.hitFlash?'#ffcf91':'#76604b';ctx.beginPath();ctx.ellipse(0,0,16,17,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d99b59';ctx.beginPath();ctx.moveTo(-10,-13);ctx.lineTo(-18,-24);ctx.lineTo(-6,-18);ctx.fill();ctx.beginPath();ctx.moveTo(10,-13);ctx.lineTo(18,-24);ctx.lineTo(6,-18);ctx.fill()}else{ctx.fillStyle='#232b22';ctx.beginPath();ctx.ellipse(0,7,12,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.hitFlash?'#fff0c4':'#89735b';ctx.beginPath();ctx.ellipse(0,0,12,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#92785c';ctx.beginPath();ctx.moveTo(-8,-7);ctx.lineTo(-11,-18);ctx.lineTo(-2,-10);ctx.moveTo(8,-7);ctx.lineTo(11,-18);ctx.lineTo(2,-10);ctx.fill()}ctx.fillStyle='#ff8960';ctx.fillRect(-5,-2,2,2);ctx.fillRect(3,-2,2,2);if(e.wind>0){ctx.strokeStyle='#ff6c48bb';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,e.r+10,-Math.PI/2,-Math.PI/2+((.6-e.wind)/.6)*Math.PI*2);ctx.stroke()}ctx.restore();ctx.fillStyle='#171915';ctx.fillRect(x-16,y-e.r-17,32,4);ctx.fillStyle='#bd6351';ctx.fillRect(x-16,y-e.r-17,32*Math.max(0,e.hp/e.max),4)}
function frame(now){requestAnimationFrame(frame);let dt=Math.min(.034,(now-(frame.last||now))/1000);frame.last=now;let mx=joy.x+((keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0)),my=joy.y+((keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0));let ml=Math.hypot(mx,my);if(ml>1){mx/=ml;my/=ml}if(ml){player.faceX=mx;player.faceY=my}const speed=player.dash>0?1:155;player.x+=(mx*speed+(player.vx||0))*dt;player.y+=(my*speed+(player.vy||0))*dt;player.vx=(player.vx||0)*Math.max(0,1-dt*7);player.vy=(player.vy||0)*Math.max(0,1-dt*7);player.dash=Math.max(0,player.dash-dt);player.invuln=Math.max(0,player.invuln-dt);attackTimer=Math.max(0,attackTimer-dt);skillCD=Math.max(0,skillCD-dt);skill2CD=Math.max(0,skill2CD-dt);if(attackHeld)attack();player.mp=Math.min(player.maxMp,player.mp+dt*2.3);if(Math.random()<dt*.4)updateHUD();
for(const e of enemies){let d=dist(player,e);e.hitFlash=Math.max(0,e.hitFlash-dt);e.phase+=dt;if(e.wind>0){e.wind-=dt;if(e.wind<=0&&dist(player,e)<e.r+28&&player.invuln<=0){player.hp=Math.max(0,player.hp-(e.type==='brute'?18:10));player.invuln=.55;particle(player.x,player.y,'#e56a53',9);updateHUD();if(player.hp<=0){player.hp=player.maxHp;player.mp=player.maxMp;player.x=0;player.y=0;player.gold=Math.max(0,player.gold-8);notify('CADI YENİLDİ','Kampa döndün · 8 Altın kaybettin.');updateHUD()}}}else if(d<210){if(d>e.r+player.r+8){e.x+=(player.x-e.x)/d*e.speed*dt;e.y+=(player.y-e.y)/d*e.speed*dt}else if(Math.random()<dt*.6)e.wind=.62}}
for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;p.vx*=.96;p.vy+=65*dt}particles=particles.filter(p=>p.life>0);drops=drops.filter(d=>d.life-->0);camera.x+=(player.x-camera.x)*Math.min(1,dt*5);camera.y+=(player.y-camera.y)*Math.min(1,dt*5);ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(W/2-camera.x,H/2-camera.y);drawGround();for(const d of drops){ctx.fillStyle=d.type==='gear'?'#f0ca72':d.type==='ore'?'#aab0a4':'#9e7c5e';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=12;ctx.beginPath();ctx.arc(d.x,d.y,6,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}for(const e of enemies)drawEnemy(e);ctx.globalAlpha=player.invuln>0&&Math.floor(now/70)%2?.35:1;ctx.fillStyle='#171d17';ctx.beginPath();ctx.ellipse(player.x,player.y+9,13,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d0b779';ctx.beginPath();ctx.arc(player.x,player.y,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='#49604a';ctx.beginPath();ctx.moveTo(player.x-9,player.y+4);ctx.lineTo(player.x-7,player.y+15);ctx.lineTo(player.x+7,player.y+15);ctx.lineTo(player.x+9,player.y+4);ctx.fill();ctx.strokeStyle='#e3d3a6';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(player.x+player.faceX*7,player.y+player.faceY*7);ctx.lineTo(player.x+player.faceX*25-player.faceY*4,player.y+player.faceY*25+player.faceX*4);ctx.stroke();for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.restore();if(labelTimer>0)labelTimer-=dt;document.querySelector('#combat-label').style.opacity=labelTimer>0?1:0;let q=nearestDrop();document.querySelector('#interact').style.opacity=q?1:.75}
requestAnimationFrame(frame);

