const backdrop=document.querySelector('#backdrop'),modal=document.querySelector('#modal');function openPanel(name){backdrop.style.display='flex';if(name==='inventory'){modal.innerHTML=`<div class="modal-head"><h2>Gezginin Çantası</h2><button class="close">×</button></div><p>Ganimetini incele. Eşya karşılaştırmaları temel hasar değerine göre hesaplanır.</p><div class="inventory-grid">${inventory.length?inventory.map((it,i)=>`<button class="item" data-equip="${i}"><strong>${it.name}</strong>${it.rarity} ${it.slot}<br>⚔ +${it.dmg} Hasar<br><span style="color:#8eaa7a">Dokun: kuşan</span></button>`).join(''):'<div class="card"><h3>Çanta boş</h3><small>Kül Geçidi yaratıklarını yen, parlayan ganimeti almak için ✧ düğmesine yaklaş.</small></div>'}</div><h3 style="font:16px Marcellus;color:#e5d3ab;margin-top:18px">Malzemeler</h3>${Object.entries(materials).map(([k,v])=>`<div class="statline"><span>${k}</span><b>${v}</b></div>`).join('')}<div class="hint">Taşıma kapasitesi: ${inventory.length}/24 · Eşyalar bu keşif boyunca saklanır.</div>`}
else if(name==='character'){modal.innerHTML=`<div class="modal-head"><h2>Gezgin · Seviye ${player.level}</h2><button class="close">×</button></div><div class="cards"><div class="card"><div class="rarity">SAVAŞÇI</div><h3>Kül Yemini</h3><small>Aktif, konumlanma odaklı yakın dövüş. Her saldırı, atılma ve büyü oyuncu girdisiyle gerçekleşir.</small></div><div class="card"><div class="rarity">SAVAŞ DEĞERLERİ</div><h3>${player.dmg} Hasar</h3><small>Can ${Math.ceil(player.hp)}/${player.maxHp}<br>Öz ${Math.floor(player.mp)}/${player.maxMp}<br>Altın ${player.gold}</small></div></div><h3 style="font:16px Marcellus;color:#e5d3ab;margin-top:18px">Silah Ustalığı</h3>${Object.entries(mastery).map(([k,v])=>`<div class="statline"><span>${k}</span><b>${v} kullanım · Kademe ${Math.floor(v/12)+1}</b></div>`).join('')}<p>Ustalık yalnızca ilgili eylemi savaşta aktif kullandığında artar. Her 12 kullanım küçük bir hasar / güç bonusu verir.</p>`}
else if(name==='tree'){let nodes=[['Kılıç Ustalığı','Temel saldırı hasarı +3',3],['Kor Korosu','Kor Alevi hasarı +25%',2],['Çevik Adım','Atılma öz bedeli −3',2],['Derin Öz','Azami öz +20',2],['Canlı Zırh','Azami can +20',2],['Patlama Ustası','Kül Patlaması yarıçapı +20%',2]];modal.innerHTML=`<div class="modal-head"><h2>Yetenek Ağı</h2><button class="close">×</button></div><p>Doğrusal olmayan ustalık dalları. Seviye atlamak 1 yetenek puanı kazandırır. Bir düğüme dokunarak aç.</p><div class="statline"><span>Dağıtılabilir puan</span><b>${treePoints}</b></div><div class="cards" style="margin-top:12px">${nodes.map(([n,d,c],i)=>`<div class="card"><div class="rarity">${i<2?'SİLAH':i<4?'ÖZ':'HAYATTA KALMA'} · ${c} PUAN</div><h3>${n}</h3><small>${d}</small><br><button class="action" data-node="${i}" ${treeBought[i]?'disabled':''}>${treeBought[i]?'AÇILDI':`AÇ · ${c} P`}</button></div>`).join('')}</div>`}
else if(name==='craft'){let can=materials['Kurt Postu']>=3&&materials['Demir Cevheri']>=2;modal.innerHTML=`<div class="modal-head"><h2>Gezgin Demirhanesi</h2><button class="close">×</button></div><p>Mağaralardan cevher, yaratıklardan bileşen topla. Üretim garantilidir; efsanevi eşya arayışı hâlâ ganimet düşüşüne bağlı.</p><div class="cards"><div class="card"><div class="rarity">SİLAH · NADİR</div><h3>Kül Döven</h3><small>⚒ 2 Demir Cevheri<br>⚒ 3 Kurt Postu<br>⚒ 35 Altın<br><br>Bir sonraki saldırı hasarını artıran dövme kılıcı.</small><br><button class="action" id="forge" ${can&&player.gold>=35?'':'disabled'}>ÜRET</button></div><div class="card"><div class="rarity">KAYNAK DÖNGÜSÜ</div><h3>Keşif alanı</h3><small>Demir: ${materials['Demir Cevheri']}<br>Kurt postu: ${materials['Kurt Postu']}<br>Kül özü: ${materials['Kül Özü']}<br>Çevredeki kaynakları topla; nadir damarlar tehlikeli bölgelerde bulunur.</small></div></div><div class="hint">Üretim, dokunmatik ekran için tek adımlı onayla çalışır.</div>`}
else if(name==='dungeon'){modal.innerHTML=`<div class="modal-head"><h2>Tehlike Mührü</h2><button class="close">×</button></div><p>İsteğe bağlı zorluk çarpanları. Savaş alanında aktif kalır. Ölümde normalde 8 altın kaybedersin; Riskli Keşif'te çantandaki malzemelerin bir kısmı da düşer.</p><div class="cards"><div class="card"><div class="rarity">GÜÇLÜ DÜŞMANLAR</div><h3>Kızıl Öfke</h3><small>Düşmanlar +%40 can ve hasar. Ganimet şansı +%35.</small><button class="action" id="rage">MÜHRÜ DEĞİŞTİR</button></div><div class="card"><div class="rarity">YÜKSEK RİSK</div><h3>Riskli Keşif</h3><small>Ölümde malzemelerinin %25'i düşer. Nadir ganimet şansı +%50.</small><button class="action" id="risk">MÜHRÜ DEĞİŞTİR</button></div></div><div class="hint">Mühürler isteğe bağlıdır. Normal keşif dengesi değiştirilmez.</div>`}
else if(name==='quest'){modal.innerHTML=`<div class="modal-head"><h2>Kamp Ateşi</h2><button class="close">×</button></div><div class="card"><div class="rarity">YARDIMCI YAN GÖREV</div><h3>Kurdun Postu</h3><small>5 kül kurdunu avla. Kısa, anlatı yükü taşımayan bir av görevi; teçhizat aralığını aşarken destek olmak için tasarlandı.</small><div class="statline"><span>İlerleme</span><b>${Math.min(kills,5)} / 5</b></div><div class="statline"><span>Ödül</span><b>60 XP · 1 Kül Özü · 30 Altın</b></div></div><p>Görev öldürme ilerlemesiyle otomatik tamamlanır; ödül doğrudan verilir.</p>`}modal.querySelector('.close')?.addEventListener('click',closePanel);modal.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{let it=inventory[+b.dataset.equip];player.dmg+=it.dmg;inventory.splice(+b.dataset.equip,1);updateHUD();openPanel('inventory');notify('EŞYA KUŞANILDI',`${it.name} · +${it.dmg} Hasar`)});modal.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>{let i=+b.dataset.node,c=[3,2,2,2,2,2][i];if(treePoints<c)return;treePoints-=c;treeBought[i]=true;if(i===0)player.dmg+=3;if(i===3){player.maxMp+=20;player.mp+=20}if(i===4){player.maxHp+=20;player.hp+=20}if(i===1)mastery['Kor Alevi']+=0;updateHUD();openPanel('tree')});modal.querySelector('#forge')?.addEventListener('click',()=>{materials['Kurt Postu']-=3;materials['Demir Cevheri']-=2;player.gold-=35;inventory.push({name:'Kül Döven',slot:'Silah',rarity:'Nadir',dmg:11+player.level});updateHUD();openPanel('craft');notify('DÖVME TAMAMLANDI','Kül Döven üretildi.')});modal.querySelector('#rage')?.addEventListener('click',()=>{rage=!rage;enemies.forEach(e=>{e.max*=rage?1.4:1/1.4;e.hp=e.max;e.speed*=rage?1.2:1/1.2});notify('KIZIL ÖFKE',rage?'Mühür etkin · Ganimet şansı yükseldi':'Mühür kaldırıldı');openPanel('dungeon')});modal.querySelector('#risk')?.addEventListener('click',()=>{risk=!risk;notify('RİSKLİ KEŞİF',risk?'Malzeme kaybı ve ganimet bonusu etkin':'Risk mührü kaldırıldı');openPanel('dungeon')})}
function closePanel(){backdrop.style.display='none'}let rage=false,risk=false;document.querySelectorAll('.nav-btn').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.panel)));document.querySelector('#interact').addEventListener('click',interact);backdrop.addEventListener('click',e=>{if(e.target===backdrop)closePanel()});

