 function updateHUD(){document.querySelector('#hp-text').textContent=Math.ceil(player.hp);document.querySelector('#mp-text').textContent=Math.floor(player.mp);document.querySelector('#level').textContent=player.level;document.querySelector('#xp').textContent=player.xp;document.querySelector('#xp-next').textContent=player.next;document.querySelector('#dmg').textContent=player.dmg;document.querySelector('#gold').textContent=player.gold;document.querySelector('#item-count').textContent=inventory.length;document.querySelector('.health').style.setProperty('--fill',`${player.hp/player.maxHp*100}%`);document.querySelector('.mana').style.setProperty('--fill',`${player.mp/player.maxMp*100}%`);document.querySelector('#quest-copy').textContent=questDone?'Tamamlandı · Ödül alındı':'5 kül kurdu avla · Ödül: 60 XP + 1 Öz'}
 function gainXP(n){player.xp+=n;if(player.xp>=player.next){player.xp-=player.next;player.level++;player.next=Math.round(player.next*1.35);player.maxHp+=12;player.hp=player.maxHp;player.dmg+=2;treePoints++;notify('SEVİYE ATLADIN',`Seviye ${player.level} · +1 Yetenek Puanı`)}updateHUD()}
